        let op = operator[i];
        let next = operand[i + 1];
        switch (op) {
            case '+':
                result += next;
                break;
            case '-':
                result -= next;
                break;
            case '*':
                result *= next;
                break;
            case '//':
                result = Math.floor(result / next);
                break;
            case '**':
                result = Math.pow(result, next);
                break;
        }
    }
    return result;
